window.__SOLAR_CONF__ = "# ============================================================================\n#  solar.conf — Solar System body definitions\n#  Parsed at startup by src/config.js. All values are SI units:\n#    mass [kg], radius [m], x/y [m], period [s], inclination/tilt [degrees]\n#\n#  Each [astral] section defines one body.\n#    star   : x, y ignored at runtime (Sun wobbles about the origin)\n#    planet : x, y = initial position relative to the Sun; the simulator gives\n#             it a circular-orbit speed v = sqrt(G*M/r), perpendicular, CCW\n#    moon   : x, y = initial offset from its parent; orbit radius and phase\n#             are derived from the offset; period sets the Kepler motion\n# ============================================================================\n\n[astral]\nname = Sun\ntype = star\nmass = 1.989e30\nradius = 6.957e8\nx = 0\ny = 0\ncolor = #ffce73\nwobble_radius = 7.4e8\nwobble_period = 3.743e8\nfact = The Sun is 99.86% of the Solar System's mass. It circles the system's barycentre, tugged mainly by Jupiter.\n\n[astral]\nname = Mercury\ntype = planet\nparent = Sun\nmass = 3.3011e+23\nradius = 2.4397e+6\nx = 3.768198e+10\ny = 2.63852e+10\ninclination = 7\ntilt = 0.03\nrotation_hours = 1407.6\ncolor = #b3a597\nfact = A year on Mercury lasts 88 days, but one solar day lasts 176 Earth days — longer than its year.\n\n[astral]\nname = Venus\ntype = planet\nparent = Sun\nmass = 4.8676e+24\nradius = 6.0518e+6\nx = -9.740724e+10\ny = 4.542174e+10\ninclination = 3.39\ntilt = 177.4\nrotation_hours = -5832.5\ncolor = #e6c07b\nfact = Venus spins backwards, and so slowly that its day is longer than its year.\n\n[astral]\nname = Earth\ntype = planet\nparent = Sun\nmass = 5.972e+24\nradius = 6.371e+6\nx = -9.455406e+10\ny = -1.126851e+11\ninclination = 0\ntilt = 23.44\nrotation_hours = 23.93\ncolor = #5da9e9\nfact = The only known world with liquid-water oceans on its surface — and the only one known to host life.\n\n[astral]\nname = Mars\ntype = planet\nparent = Sun\nmass = 6.4185e+23\nradius = 3.3895e+6\nx = 1.461423e+11\ny = -1.461423e+11\ninclination = 1.85\ntilt = 25.19\nrotation_hours = 24.62\ncolor = #e07a5f\nfact = Home to Olympus Mons, a volcano nearly three times the height of Mount Everest.\n\n[astral]\nname = Jupiter\ntype = planet\nparent = Sun\nmass = 1.8981e+27\nradius = 6.9911e+7\nx = 1.286531e+11\ny = 7.296282e+11\ninclination = 1.3\ntilt = 3.13\nrotation_hours = 9.93\ncolor = #d9a878\nfact = More than twice as massive as all the other planets combined. Its Great Red Spot has raged for centuries.\n\n[astral]\nname = Saturn\ntype = planet\nparent = Sun\nmass = 5.6846e+26\nradius = 5.8232e+7\nx = -1.350531e+12\ny = 1.181562e+11\ninclination = 2.49\ntilt = 26.73\nrotation_hours = 10.66\ncolor = #e3cfa2\nfact = Its rings are over 270,000 km wide yet in places only about ten metres thick.\n\n[astral]\nname = Uranus\ntype = planet\nparent = Sun\nmass = 8.681e+25\nradius = 2.5362e+7\nx = -2.39456e+11\ny = -2.736995e+12\ninclination = 0.77\ntilt = 97.77\nrotation_hours = -17.24\ncolor = #9ad5d8\nfact = Uranus rolls around the Sun on its side — its axis is tilted almost 98 degrees.\n\n[astral]\nname = Neptune\ntype = planet\nparent = Sun\nmass = 1.0243e+26\nradius = 2.4622e+7\nx = 4.478632e+12\ny = 3.918296e+11\ninclination = 1.77\ntilt = 28.32\nrotation_hours = 16.11\ncolor = #6a8fd8\nfact = The windiest world in the Solar System, with supersonic gusts over 2,000 km/h.\n\n[astral]\nname = Moon\ntype = moon\nparent = Earth\nmass = 7.342e+22\nradius = 1.7374e+6\nx = 2.944675e+8\ny = 2.470876e+8\nperiod = 2.360621e+6\ncolor = #c9c5bd\nfact = The Moon drifts away from Earth by about 3.8 cm every year.\n\n[astral]\nname = Phobos\ntype = moon\nparent = Mars\nmass = 1.0659e+16\nradius = 1.1267e+4\nx = 9.233557e+6\ny = 1.628125e+6\nperiod = 2.755296e+4\ncolor = #a89c90\nfact = Orbits Mars faster than Mars rotates — it rises in the west and sets in the east, twice a day.\n\n[astral]\nname = Deimos\ntype = moon\nparent = Mars\nmass = 1.4762e+15\nradius = 6.2e+3\nx = -2.204801e+7\ny = -8.024819e+6\nperiod = 1.090714e+5\ncolor = #b0a498\nfact = One of the smallest known moons — its surface gravity is so weak you could jump off it.\n\n[astral]\nname = Io\ntype = moon\nparent = Jupiter\nmass = 8.9319e+22\nradius = 1.8216e+6\nx = 4.073309e+8\ny = 1.09144e+8\nperiod = 1.528502e+5\ncolor = #e8d44d\nfact = The most volcanically active world known, squeezed and heated by Jupiter's relentless tides.\n\n[astral]\nname = Europa\ntype = moon\nparent = Jupiter\nmass = 4.7998e+22\nradius = 1.5608e+6\nx = -4.312462e+8\ny = 5.139392e+8\nperiod = 3.068237e+5\ncolor = #d8cfc4\nfact = Beneath its cracked ice shell hides a salty ocean with more water than all of Earth's seas.\n\n[astral]\nname = Ganymede\ntype = moon\nparent = Jupiter\nmass = 1.4819e+23\nradius = 2.6341e+6\nx = -3.660984e+8\ny = -1.005847e+9\nperiod = 6.181574e+5\ncolor = #b5aa9d\nfact = The largest moon in the Solar System — bigger than the planet Mercury.\n\n[astral]\nname = Callisto\ntype = moon\nparent = Jupiter\nmass = 1.0759e+23\nradius = 2.4103e+6\nx = 1.630466e+9\ny = -9.4135e+8\nperiod = 1.44193e+6\ncolor = #8f867d\nfact = The most heavily cratered world in the Solar System — a fossil of the early solar nebula.\n\n[astral]\nname = Mimas\ntype = moon\nparent = Saturn\nmass = 3.7493e+19\nradius = 1.982e+5\nx = 1.84814e+8\ny = 1.616913e+7\nperiod = 8.142336e+4\ncolor = #c2bdb6\nfact = Its giant crater Herschel makes it look uncannily like the Death Star.\n\n[astral]\nname = Enceladus\ntype = moon\nparent = Saturn\nmass = 1.0802e+20\nradius = 2.521e+5\nx = 6.160411e+7\ny = 2.299097e+8\nperiod = 1.183853e+5\ncolor = #e8e6e1\nfact = Geysers at its south pole vent an underground ocean straight into space, feeding Saturn's E ring.\n\n[astral]\nname = Tethys\ntype = moon\nparent = Saturn\nmass = 6.1745e+20\nradius = 5.31e+5\nx = -2.413713e+8\ny = 1.6901e+8\nperiod = 1.631059e+5\ncolor = #cfc9c1\nfact = Almost pure water ice — one of the most reflective bodies in the Solar System.\n\n[astral]\nname = Dione\ntype = moon\nparent = Saturn\nmass = 1.0955e+21\nradius = 5.614e+5\nx = -3.091644e+8\ny = -2.164792e+8\nperiod = 2.364682e+5\ncolor = #c6c0b8\nfact = Wispy canyons of bright ice cliffs streak across its trailing hemisphere.\n\n[astral]\nname = Rhea\ntype = moon\nparent = Saturn\nmass = 2.3065e+21\nradius = 7.638e+5\nx = 1.36408e+8\ny = -5.090815e+8\nperiod = 3.90312e+5\ncolor = #bdb7af\nfact = Saturn's second-largest moon may have its own faint ring system.\n\n[astral]\nname = Titan\ntype = moon\nparent = Saturn\nmass = 1.3452e+23\nradius = 2.5747e+6\nx = 1.21722e+9\ny = -1.06493e+8\nperiod = 1.377648e+6\ncolor = #d8a94e\nfact = The only moon with a thick atmosphere, plus rivers and seas of liquid methane.\n\n[astral]\nname = Iapetus\ntype = moon\nparent = Saturn\nmass = 1.8056e+21\nradius = 7.345e+5\nx = 1.50507e+9\ny = 3.227634e+9\nperiod = 6.853421e+6\ncolor = #a79d90\nfact = Two-faced: one hemisphere is dark as coal, the other bright as snow.\n\n[astral]\nname = Miranda\ntype = moon\nparent = Uranus\nmass = 6.59e+19\nradius = 2.358e+5\nx = 1.172672e+8\ny = 5.468258e+7\nperiod = 1.221264e+5\ncolor = #bfbab3\nfact = A patchwork world with cliffs up to 20 km tall — the tallest known in the Solar System.\n\n[astral]\nname = Ariel\ntype = moon\nparent = Uranus\nmass = 1.353e+21\nradius = 5.789e+5\nx = -1.663803e+7\ny = 1.901736e+8\nperiod = 2.177626e+5\ncolor = #c8c3bc\nfact = The brightest of Uranus's moons, scarred by broad ice-flooded valleys.\n\n[astral]\nname = Umbriel\ntype = moon\nparent = Uranus\nmass = 1.172e+21\nradius = 5.847e+5\nx = -2.569363e+8\ny = 6.884587e+7\nperiod = 3.580589e+5\ncolor = #8a847c\nfact = The darkest of Uranus's large moons, with a mysterious bright ring called the Fluorescent Cheerio.\n\n[astral]\nname = Titania\ntype = moon\nparent = Uranus\nmass = 3.527e+21\nradius = 7.884e+5\nx = -2.500277e+8\ny = -3.570766e+8\nperiod = 7.521898e+5\ncolor = #b3ada5\nfact = Uranus's largest moon, laced with enormous fault canyons from an expanding interior.\n\n[astral]\nname = Oberon\ntype = moon\nparent = Uranus\nmass = 3.014e+21\nradius = 7.614e+5\nx = 3.346933e+8\ny = -4.779916e+8\nperiod = 1.163203e+6\ncolor = #a8a29a\nfact = The outermost of Uranus's big moons, its old cratered face darkened by ancient ice chemistry.\n\n[astral]\nname = Triton\ntype = moon\nparent = Neptune\nmass = 2.139e+22\nradius = 1.3534e+6\nx = 2.280353e+8\ny = 2.717619e+8\nperiod = 5.077642e+5\nretrograde = true\ncolor = #d3cdc5\nfact = Orbits Neptune backwards — a captured Kuiper Belt world with geysers of nitrogen ice.\n";
